                    int flags = data.readUnsignedByte();
                    if (BitUtil.from(flags, 4) > 0) {
                        position.set("tag" + index + "Uuid", ByteBufUtil.hexDump(data.readSlice(16)));
                        position.set("tag" + index + "Major", data.readUnsignedShort());
                        position.set("tag" + index + "Minor", data.readUnsignedShort());
