                    position.set("tag" + index + "Rssi", (int) data.readByte());
                    if (BitUtil.check(flags, 1)) {
                        position.set("tag" + index + "Battery", data.readUnsignedShort() * 0.01);
                    }
                    if (BitUtil.check(flags, 2)) {
                        position.set("tag" + index + "Temp", data.readUnsignedShort());
                    }
                    index += 1;
